      "check": {
        "prompt_fil": "Humihingi ang barangay meeting ng paliwanag sa missed visits. Ano ang ibabahagi?",
        "prompt_en": "A barangay meeting asks about missed visits. What should be shared?",
        "options": [
          {
            "fil": "Ang pinagsamang childcare barrier at tanong tungkol sa iskedyul.",
            "en": "The aggregated childcare barrier and a question about scheduling."
          },
          {
            "fil": "Mga larawan ng household forms para kumpleto.",
            "en": "Photos of household forms for completeness."
